INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65769203', 65769203, 'analyze_legacy', 'Kota Pasuruan', 'kabkota', 'RSUD DR. R. SOEDARSONO', 'Belanja Bahan-Bahan Lainnya (sub kegiatan Pelayanan Laundry/Binatu)', 'Barang', 'E-Purchasing', 'Jawa Timur, Pasuruan (Kota)', 171999000, 'February 2026', 'BLUD', 1, 1, '30 jerigen Alkali (builder), 35 jerigen Detergent, 30 jerigen Emulsifier, 8 jerigen Oxchlor, 18 jerigen Oxferox Bleach, 30 jerigen Pewangi Pakaian, 30 jerigen Softener, 18 jerigen Sour (Penetral)', 'Pengadaan bahan habis pakai untuk keperluan instalasi laundry di rumah sakit meliputi Alkali (builder), Detergent, Emulsifier, Oxchlor, Oxferox Bleach, Pewangi Pakaian, Softener, Sour (Penetral)', 'chemical laundry khusus linen dengan kemasan jerigen/galon (isi minimal 20 liter) yang memiliki spesifikasi sbb : - alkali (builder) : pH tinggi untuk penghilang kotoran berat, bentuk cair/serbuk, aman tidak merusak kain/linen - detergent : surfaktan anionik/ionik, efektif membersihkan kotoran organik dan anorganik, bentuk cair/serbuk, aman tidak merusak kain/linen - emulsifier : pengemulsi minyak, lemak, dan noda berminyak, bentuk cair, stabil pada suhu tinggi, kompatibel dengan detergent/alkali - Oxchlor : pemutih dan desinfektan berbasis klorin, bentuk cair, aman tidak merusak kain/linen - Oxferox bleach : pemutih oksigen untuk linen berwarna dan putih, bentuk cair/serbuk, aman tidak merusak warna kain/linen - Pewangi : pewangi pakaian, bentuk cair, aroma lembut, tidak terlalu menyengat, awet, tidak menimbulkan iritasi, aman tidak merusak kain/linen - Softener : Pelembut pakaian, aman untuk kulit sensitif, aman tidak merusak serat kain/linen - Sour (Penetral) : menetralkan sisa alkali dan menurunkan pH, bentuk cair, pH asam (<7), tidak membuat iritasi kulit, aman tidak merusak kain/linen', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2342249);
