INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65732409', 65732409, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Direktorat Jenderal Ketahanan Perwilayahan dan Akses Industri Internasional', 'Jasa Konsultansi Perorangan Penyusunan Dampak Kuantitatif Peningkatan Belanja Litbang Terhadap Produktivitas Dan Indikator Perekonomian', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 75000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 75000000 )', 'Jasa Konsultansi Perorangan Penyusunan Dampak Kuantitatif Peningkatan Belanja Litbang Terhadap Produktivitas Dan Indikator Perekonomian', 'Ruang Lingkup Pekerjaan Ruang lingkup kegiatan ini antara lain: a. Kerangka konseptual dan teoritis Menjelaskan keterkaitan antara belanja litbang dengan produktivitas, inovasi, kinerja perekonomian, baik dalam level mikro dan makro, termasuk mekanisme transmisi dampaknya. b. Cakupan belanja litbang Analisis belanja litbang yang bersumber dari dunia usaha, khususnya sektor industri, dengan penekanan pada peningkatan intensitas dan efisiensi belanja litbang. c. Analisis dampak kuantitatif pada level mikro Pengukuran dampak peningkatan belanja litbang (minimal 2% terhadap total penjualan) terhadap indikator ekonomi mikro, seperti produktivitas industri, efisiensi produksi, capital output ratio dan daya saing sektor industri. d. Analisis dampak kuantitatif pada level makro Pengukuran dampak peningkatan belanja litbang (minimal 2% terhadap total penjualan) terhadap indikator perekonomian makro, seperti pertumbuhan ekonomi, pertumbuhan investasi, pertumbuhan sektor industri, produktivitas nasional, serta implikasi fiskal terhadap penerimaan negara. e. Pendekatan dan metodologi kuantitatif Penggunaan metode kuantitatif untuk menganalisis dampak peningkatan belanja litbang terhadap indikator perekonomian adalah menggunakan model ekonomi keseimbangan umum berbasis data input output terbaru. f. Analisis jangka waktu dampak (time lag analysis) Identifikasi horizon waktu munculnya dampak peningkatan belanja litbang (minimal 2% terhadap total penjualan) terhadap berbagai indikator ekonomi (jangka pendek dan jangka panjang) g. Implikasi kebijakan dan rekomendasi Perumusan implikasi kebijakan berbasis hasil kuantifikasi dampak, termasuk rekomendasi strategis untuk optimalisasi belanja litbang dalam mendukung pertumbuhan ekonomi dan daya saing nasional', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2346214);
