INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65823739', 65823739, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pemeliharaan Groundtank', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 27805500, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 Unit', 'a. Groundtank berada dalam kondisi bersih dari lumpur, pasir, lumut, dan kotoran setelah dilakukan pembersihan. b. Dinding, lantai, dan sudut tangki dalam kondisi bersih dan layak operasional. c. Sistem pembuangan, saluran, dan akses groundtank berfungsi normal tanpa sumbatan. d. Kualitas air dalam tangki layak digunakan untuk operasional sesuai fungsi distribusi air gedung. e. Hasil pekerjaan didukung dengan laporan pelaksanaan dan dokumentasi pekerjaan.', '1) Persiapan Pekerjaan a. Koordinasi dengan pihak pengelola gedung sebelum pelaksanaan pekerjaan. b. Penutupan sementara aliran air masuk dan keluar (isolasi valve) serta pengosongan tangki. c. Pemeriksaan kondisi keselamatan ruang terbatas (confined space), termasuk ventilasi dan akses masuk. 2) Pekerjaan Pembersihan a. Pengangkatan lumpur, pasir, dan endapan dari dasar tangki secara manual maupun menggunakan peralatan pendukung. b. Pembersihan lantai, dinding, sudut tangki, serta kompartemen tangki dari kotoran dan biofilm. c. Penyemprotan permukaan tangki menggunakan air bertekanan (jet cleaning). d. Pembersihan saluran masuk, keluar, dan akses tangki dari sumbatan atau kotoran. 3) Pembilasan dan Pengembalian Operasional a. Pembilasan tangki hingga air buangan bersih. b. Pemeriksaan kondisi akhir tangka untuk memastikan tidak ada sisa kotoran. c. Pengisian kembali tangka dan pengembalian sistem distribusi air ke kondisi normal. 4) Pengangkutan Limbah Pengumpulan dan pengangkutan lumpur serta sisa kotoran hasil pembersihan ke tempat pembuangan sesuai ketentuan. 5) Pelaporan a. Penyusunan laporan hasil pekerjaan. b. Dokumentasi foto setidaknya kondisi sebelum, saat, dan setelah pembersihan. 1. Ground Water Tank kapasitas 235 m3 : 1 Unit 2. Ground Water Tank kapasitas 75 m3 : 1 Unit 3. Ground Water Tank kapasitas 24 m3 : 1 Unit', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2349560);
